const $=s=>document.querySelector(s); let role='staff',page='Overview',selected=0,filter='';
const projects=[{id:'SH-2026-024',name:'The Lawson House',client:'Emma & James Lawson',place:'Waikato',model:'Gable 120',stage:'Design & engineering',progress:40,date:'28 Oct 2026'},{id:'SH-2026-021',name:'Coastal Retreat',client:'Sarah Mitchell',place:'Bay of Plenty',model:'Gable 90',stage:'Manufacturing',progress:65,date:'04 Nov 2026'},{id:'SH-2026-018',name:'Ridgeview Family Home',client:'Daniel & Mia Wilson',place:'Canterbury',model:'Gable 160',stage:'Contractor build',progress:80,date:'12 Nov 2026'}];
let leads=JSON.parse(localStorage.getItem('sh-demo-leads')||'null')||[{name:'Oliver Thompson',region:'Auckland',source:'Website enquiry',stage:'Qualified',value:145000},{name:'Amelia Roberts',region:'Waikato',source:'Referral',stage:'Proposal',value:189000},{name:'Noah Williams',region:'Wellington',source:'Home show',stage:'New lead',value:128000}];
let bids=JSON.parse(localStorage.getItem('sh-demo-bids')||'[]');let award=localStorage.getItem('sh-demo-award')||'';
const money=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD',minimumFractionDigits:0,maximumFractionDigits:2}).format(n);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={staff:'Shed House team',customer:'Customer',contractor:'Contractor'};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function go(p){page=p;filter='';render()}
function login(){ $('#app').innerHTML=`<div class="login"><section class="login-art"><img class="logo" src="assets/logo-white.svg" alt="Shed House"><div><div class="eyebrow" style="color:#faa21f">SHED HOUSE PORTAL</div><h1>From first idea.<br>To a place called home.</h1><p>One connected workspace for your Shed House journey, your team, and the people who bring it to life.</p></div><p>Clarity at every stage.</p></section><section class="login-form"><div class="eyebrow">WELCOME TO YOUR WORKSPACE</div><h1>Your project starts here.</h1><p>Choose a role to explore the first portal concept.</p><div class="roles">${Object.keys(names).map(r=>`<button data-role="${r}" class="${r===role?'selected':''}">${r==='staff'?'Shed House':names[r]}</button>`).join('')}</div><div class="card" style="background:var(--linen)"><strong>SHP 1.2 · Interactive workspaces</strong><p>This preview uses fictional data. Role selection demonstrates the planned experience; it does not authenticate an account.</p></div><button class="primary" style="margin-top:25px" id="enter">Explore ${names[role]} workspace →</button><p class="small" style="margin-top:20px">Secure sign-in, invitation-only access and account recovery are planned for the operational phase.</p></section></div>`;document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;login()});$('#enter').onclick=()=>go('Overview')}
function heading(title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">YOUR WORKSPACE / ${page.toUpperCase()}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function table(){let list=projects.filter((p,i)=>(role==='staff'||role==='customer'&&i===0||role==='contractor'&&(i===2||i===0&&!!award))&&`${p.name} ${p.client} ${p.id}`.toLowerCase().includes(filter));return `<div class="table-wrap"><table><thead><tr><th>Project / customer</th><th>Current stage</th><th>Progress</th><th>Next milestone</th><th></th></tr></thead><tbody>${list.map(p=>`<tr class="project-row" data-project="${projects.indexOf(p)}"><td><strong><button data-project="${projects.indexOf(p)}" style="text-align:left;padding:0">${p.name}</button></strong><span class="small">${p.id} · ${p.client}</span></td><td><span class="tag ${p.progress<50?'amber':'grey'}">${p.stage}</span></td><td><div class="progress"><span class="small">${p.progress}%</span><div class="bar"><i style="width:${p.progress}%"></i></div></div></td><td>${p.date}</td><td>↗</td></tr>`).join('')||'<tr><td colspan="5">No matching projects.</td></tr>'}</tbody></table></div>`}
function overview(){return heading(role==='staff'?'A clear view. A stronger business.':role==='customer'?'Your home, taking shape.':'Build your next opportunity.',role==='staff'?'Welcome back. Here’s what’s moving across Shed House.':'Stay connected to your projects, milestones and next steps.')+`<div class="banner"><div><div class="eyebrow">${role==='staff'?'OCTOBER 2026 · BUSINESS SNAPSHOT':'YOUR SHED HOUSE JOURNEY'}</div><h2>${role==='staff'?'Good foundations. Great momentum.':currentProject().name}</h2><p>${role==='staff'?`${projects.length} confirmed projects. One shared view from sale to handover.`:'Every milestone, every responsibility, all in one place.'}</p></div><button class="secondary" data-go="Projects">View projects ↗</button></div><div class="stats">${(role==='staff'?[['Sales this month','$462,000','77% of $600,000 target'],['Active leads',String(leads.length),'Across your sales pipeline'],['Confirmed projects',String(projects.length),'Design through construction'],['Open tenders','2','Contractor opportunities']]:[['Project progress',currentProject().progress+'%','Across the full build timeline'],['Next milestone',currentProject().date.replace(' 2026',''),'2026 · upcoming'],['Open tenders','2','Marketplace opportunities'],['Your workspace',role==='customer'?'SHC':'Partner','Role preview']]).map(x=>`<div class="card stat"><span class="small">${x[0]}</span><strong>${x[1]}</strong><span class="small">${x[2]}</span></div>`).join('')}</div><div class="grid"><section class="card"><div class="card-top"><h2>${role==='staff'?'Sales performance':'Your next steps'}</h2><button class="link" data-go="${role==='staff'?'Sales & CRM':'Projects'}">View details</button></div>${role==='staff'?`<div style="display:flex;justify-content:space-between"><span class="small">Monthly revenue target</span><strong>$462k / $600k</strong></div><div class="bar"><i style="width:77%"></i></div><p class="small">$138,000 remaining to reach October’s objective.</p><div class="pipeline">${[['New lead',leads.filter(l=>l.stage==='New lead').length],['Qualified',leads.filter(l=>l.stage==='Qualified').length],['Proposal',leads.filter(l=>['Pricing','Proposal'].includes(l.stage)).length],['Negotiation',leads.filter(l=>['Negotiation','Contract ready'].includes(l.stage)).length],['Confirmed',leads.filter(l=>l.stage==='Confirmed').length]].map(x=>`<div><span class="small">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div>`:`<h3>${role==='customer'?'Review engineering drawings':'Confirm site readiness'}</h3><p>${role==='customer'?'Your Shed House team is preparing the design package. Review the project timeline to see the next approval and tender steps.':'Coordinate the next construction milestone with the client and check the agreed contractor scope.'}</p><button class="primary" data-go="Projects">Open project timeline →</button>`}</section><section class="card"><div class="card-top"><h2>Coming up</h2><span class="tag amber">${permittedProjects().length} project milestones</span></div>${[['28 OCT','Lawson design approval','Shed House · Design & engineering'],['04 NOV','Coastal kit production','Shed House · Manufacturing'],['12 NOV','Ridgeview site review','Contractor · Construction']].filter((x,i)=>role==='staff'||role==='customer'&&i===0||role==='contractor'&&(i===2||i===0&&!!award)).map(x=>`<div class="activity"><span class="dot"></span><div><span class="eyebrow">${x[0]}</span><h3 style="margin:7px 0">${x[1]}</h3><span class="small">${x[2]}</span></div></div>`).join('')}</section></div><section class="card"><div class="card-top"><h2>Confirmed projects</h2><button class="link" data-go="Projects">View all projects →</button></div>${table()}</section>`}
function projectPage(){const p=projects[selected];return heading(p.name,`${p.id} · ${p.client} · ${p.place} · ${p.model}`,`<button class="secondary" data-go="Projects">← All projects</button>`)+`<div class="grid"><section class="card"><div class="card-top"><h2>Full project timeline</h2><span class="tag amber">${p.progress}% complete</span></div><p>Track Shed House’s contracted scope and the wider customer build together. Demonstration stages must be matched to the signed contract.</p><div class="timeline">${[['Contract & deposit','Shed House','Contract confirmed and project established.','Complete'],['Design & engineering','Shed House','Design package, specifications and customer approval.',p.progress>40?'Complete':'In progress'],['Consent & site preparation','Customer / selected contractor','Coordinate approvals, services, access and foundations.','Planned'],['Kit manufacturing & delivery','Shed House','Production scheduling and delivery of the contracted kit.',p.progress>=65?'In progress':'Planned'],['Construction & fit-out','Selected contractor','Deliver the awarded scope under the customer’s contractor agreement.',p.progress>=80?'In progress':'Awaiting tender'],['Final checks & handover','Customer / selected contractor','Complete inspections, outstanding items and project records.','Planned']].map((x,i)=>`<div class="step ${x[3]==='Complete'?'done':''}"><span class="number">${x[3]==='Complete'?'✓':i+1}</span><div><span class="scope">${x[1]}</span><h3>${x[0]}</h3><p class="small">${x[2]}</p></div><span class="small">${x[3]}</span></div>`).join('')}</div></section><div><section class="card"><h2>Project team</h2><div class="activity"><span class="avatar">SH</span><div><strong>Shed House</strong><p class="small">Design, kit supply & contracted delivery</p></div></div><div class="activity"><span class="avatar">CL</span><div><strong>${p.client}</strong><p class="small">Customer · Project owner</p></div></div><div class="activity"><span class="avatar">CO</span><div><strong>${selected===0&&award?escape(award):selected===2?'Ridgeview Construction':'Contractor to be appointed'}</strong><p class="small">Through the tender marketplace</p></div></div></section><section class="card" style="margin-top:20px;background:var(--linen)"><h2>The next chapter</h2><p>Bring your wider build to market. Compare proposals and connect the successful contractor to your timeline.</p><button class="primary" data-go="Tender marketplace">Explore marketplace →</button></section></div></div>`}
function crm(){return heading('Relationships that build business.','Manage enquiries, follow-ups and opportunities.',`<button class="primary" id="addLead">+ Add lead</button>`)+`<div class="stats">${[['Pipeline value',money(leads.reduce((a,l)=>a+l.value,0))],['Active leads',leads.length],['Sales target','$600,000'],['Target achieved','77%']].map(x=>`<div class="card stat"><span class="small">${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><section class="card"><div class="card-top"><h2>Lead pipeline</h2><span class="small">Saved on this browser · demo only</span></div><div class="table-wrap"><table><thead><tr><th>Contact</th><th>Source</th><th>Stage</th><th>Estimated value</th><th>Next action</th></tr></thead><tbody>${leads.filter(l=>`${l.name} ${l.region}`.toLowerCase().includes(filter)).map(l=>`<tr><td><strong>${escape(l.name)}</strong>${escape(l.region)}</td><td>${escape(l.source)}</td><td><select aria-label="Stage for ${escape(l.name)}" data-lead="${leads.indexOf(l)}">${['New lead','Qualified','Pricing','Proposal','Negotiation','Contract ready','Confirmed'].map(s=>`<option ${l.stage===s?'selected':''}>${s}</option>`).join('')}</select></td><td>${money(l.value)}</td><td>Arrange follow-up</td></tr>`).join('')}</tbody></table></div></section><div class="banner" style="margin-top:24px"><div><h2>Turn interest into a conversation.</h2><p>Capture a new enquiry with its source, location and estimated value.</p></div><button class="secondary" id="capture">Capture enquiry →</button></div>`}
function marketplace(){return heading('The right people. The next stage.','Connect customer projects with contractors through the tender marketplace.')+`<div class="banner"><div><h2>A connected handover</h2><p>Once a customer selects a successful contractor, their appointment appears in the project timeline.</p></div><span class="tag amber">TMP · Concept</span></div><div class="tenders">${[['Lawson House · Construction package','Waikato','Foundations, kit erection and weather-tight shell','$180k–$220k','30 Oct 2026'],['Coastal Retreat · Interior fit-out','Bay of Plenty','Interior lining, joinery and finishing trades','$65k–$85k','06 Nov 2026']].map((x,i)=>`<section class="card tender"><div class="card-top"><span class="tag ${award&&i===0?'':'amber'}">${award&&i===0?'Contractor selected':'Open tender'}</span><span class="small">TMP-00${i+1}</span></div><h2>${x[0]}</h2><p>${x[1]} · ${x[2]}</p><div class="activity"><div><span class="small">Indicative budget</span><h3>${x[3]}</h3></div><div style="margin-left:auto"><span class="small">Closes</span><h3>${x[4]}</h3></div></div><button class="${role==='contractor'?'primary':'secondary'}" data-tender="${i}">${role==='contractor'?'Prepare demo proposal':'View tender & proposals'} →</button></section>`).join('')}</div>`}
function tenderDetail(i){const offers=i===0?[{name:'Summit Construction',amount:198000},{name:'Northline Builders',amount:212000},...bids.filter(b=>b.tender===i)]:bids.filter(b=>b.tender===i);$('#modal').innerHTML=role==='contractor'?`<form id="bidForm"><h2>Prepare a demo proposal</h2><p>For TMP-00${i+1}. This proposal is saved locally and is not sent to a customer.</p><label>Business name</label><input aria-label="Name" name="name" required maxlength="100"><label>Proposal amount (NZD)</label><input aria-label="Proposal amount" name="amount" type="number" min="1" max="10000000" required><div class="dialog-actions"><button type="button" class="secondary" id="close">Cancel</button><button class="primary">Save demo proposal</button></div></form>`:`<h2>TMP-00${i+1} · Tender proposals</h2><p>Fictional proposals for concept review. A real award will require customer approval and an agreed contractor contract.</p>${offers.map((b,k)=>`<div class="activity"><div><strong>${escape(b.name)}</strong><p>${money(b.amount)}</p></div>${role==='customer'&&i===0?`<button class="secondary" data-award="${k}" style="margin-left:auto">${award===b.name?'Selected':'Select in demo'}</button>`:''}</div>`).join('')||'<p>No proposals yet.</p>'}<div class="dialog-actions"><button class="secondary" id="close">Close</button></div>`;$('#modal').showModal();$('#close').onclick=()=>$('#modal').close();if($('#bidForm'))$('#bidForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);bids.push({tender:i,name:f.get('name'),amount:Number(f.get('amount'))});localStorage.setItem('sh-demo-bids',JSON.stringify(bids));$('#modal').close();toast('Demo proposal saved on this browser');render()};document.querySelectorAll('[data-award]').forEach(b=>b.onclick=()=>{award=offers[Number(b.dataset.award)].name;localStorage.setItem('sh-demo-award',award);notifyProject({title:'Demo contractor selected',message:`${award} selected for the Lawson tender. Confirm actual contract and scope before appointment.`,roles:['staff','customer','contractor'],projectId:projects[0].id,kind:'award'});$('#modal').close();toast('Demo contractor appointment added to the Lawson timeline');render()})}
function addLead(){ $('#modal').innerHTML=`<form id="leadForm"><h2>Capture a new enquiry</h2><p>Add a demonstration lead to the sales pipeline.</p><label>Contact name</label><input aria-label="Name" name="name" required maxlength="100"><label>Region</label><input aria-label="Region" name="region" required maxlength="80"><label>Lead source</label><select aria-label="Lead source" name="source"><option>Website enquiry</option><option>Referral</option><option>Home show</option><option>Social campaign</option></select><label>Estimated value (NZD)</label><input aria-label="Estimated value" name="value" type="number" min="0" max="10000000" required><div class="dialog-actions"><button type="button" class="secondary" id="close">Cancel</button><button class="primary">Save lead</button></div></form>`;$('#modal').showModal();$('#close').onclick=()=>$('#modal').close();$('#leadForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);leads.push({name:f.get('name'),region:f.get('region'),source:f.get('source'),value:Number(f.get('value')),stage:'New lead'});localStorage.setItem('sh-demo-leads',JSON.stringify(leads));$('#modal').close();render();toast('Lead added to the demo pipeline')}}
function marketing(){return heading('Give every enquiry a direction.','Sales targets, lead generation and marketing objectives in one view.')+`<div class="grid"><section class="card"><h2>October sales objective</h2><h1>$462,000 <span class="small">/ $600,000</span></h1><div class="bar"><i style="width:77%"></i></div><p>Monthly target · NZD · demonstration figures</p><div class="activity"><strong>Objective</strong><span style="margin-left:auto">Confirm 4 new projects</span></div><div class="activity"><strong>Progress</strong><span style="margin-left:auto">3 confirmed · 1 remaining</span></div></section><section class="card"><h2>Lead generator</h2><p>Capture website, referral, event and campaign enquiries into CRM.</p><button class="primary" id="capture">+ Capture enquiry</button><p class="small" style="margin-top:20px">Phase 02 connects website forms and assigns follow-up owners automatically.</p></section></div><section class="card"><h2>Marketing objectives</h2>${[['Spring build campaign','Generate 20 qualified website enquiries','12 / 20 enquiries',60],['Referral programme','Create 6 customer introductions','4 / 6 introductions',67],['Regional home show','Book 10 design consultations','7 / 10 consultations',70]].map(x=>`<div class="activity"><div style="width:100%"><h3>${x[0]}</h3><p>${x[1]}</p><div class="bar"><i style="width:${x[3]}%"></i></div><span class="small">${x[2]} · illustrative target</span></div></div>`).join('')}</section>`}
function roadmap(){return heading('Built to grow with Shed House.','A phased foundation for the portal, project delivery and marketplace.')+`<div class="roadmap">${[['01','Concept & experience','Current phase',['Brand system and responsive workspace','Staff, customer and contractor previews','CRM capture and sales objectives','Shared timeline and tender demo']],['02','Secure operational portal','Next phase',['Invitation-only account provisioning','Server-enforced roles and project access','Persistent database and document storage','CRM ownership, audit history and notifications']],['03','Tender marketplace','Future phase',['Contractor onboarding and verification','Tender documents and scoped proposals','Customer comparison and award workflow','Contractor milestones and handover records']]].map(x=>`<section class="card"><span class="tag amber">PHASE ${x[0]} · ${x[2]}</span><h2 style="margin-top:20px">${x[1]}</h2><ul>${x[3].map(t=>`<li>${t}</li>`).join('')}</ul></section>`).join('')}</div><section class="card" style="margin-top:24px"><h2>Access model</h2><div class="table-wrap"><table style="margin-top:24px"><thead><tr><th>Role</th><th>Workspace access</th><th>Project responsibility</th></tr></thead><tbody><tr><td>Shed House (SH)</td><td>Sales, CRM, objectives and assigned projects</td><td>Manage contracted milestones and delivery</td></tr><tr><td>Customer (SHC)</td><td>Own projects and own tender proposals</td><td>Approve decisions and select contractors</td></tr><tr><td>Contractor</td><td>Eligible tenders and awarded projects</td><td>Submit proposals and update contracted build stages</td></tr></tbody></table></div><p>To avoid ambiguity, the interface uses “Portal” and “Project” in full: SHP currently names both in the brief.</p></section>`}
function render(){const menu=role==='staff'?['Overview','Sales & CRM','Projects','Tender marketplace','Sales & marketing','Development roadmap']:['Overview','Projects','Tender marketplace','Development roadmap'];if(!menu.includes(page)&&page!=='Project detail')page='Overview';$('#app').innerHTML=`<aside><img class="logo" src="assets/logo-white.svg" alt="Shed House"><div class="eyebrow">PORTAL / ${names[role]}</div><nav>${menu.map((m,i)=>`<button data-go="${m}" class="${page===m||page==='Project detail'&&m==='Projects'?'active':''}"><span>${['▦','◈','▤','⇄','◎','◇'][i]}</span>${m}</button>`).join('')}</nav><div class="aside-bottom"><span class="tag amber">PHASE 01</span><p style="color:#a8babd">Connected from concept<br>through to completion.</p><button class="link" style="color:white" id="signout">← Return to role selection</button></div></aside><div class="shell"><header><span class="small">Shed House / ${names[role]}</span><input id="search" aria-label="Search projects or leads" placeholder="Search projects or leads…" value="${escape(filter)}"><select id="role" aria-label="Preview role">${Object.keys(names).map(r=>`<option value="${r}" ${r===role?'selected':''}>${names[r]} preview</option>`).join('')}</select><span class="avatar">${role==='staff'?'SH':role==='customer'?'EL':'CO'}</span></header><main>${page==='Overview'?overview():page==='Projects'?heading('Every project. One connected journey.','Confirmed projects from Shed House contract through the full customer build.')+`<section class="card">${table()}</section>`:page==='Project detail'?projectPage():page==='Sales & CRM'?crm():page==='Tender marketplace'?marketplace():page==='Sales & marketing'?marketing():roadmap()}<footer>SHED HOUSE PORTAL · PHASE 01 CONCEPT · Fictional demonstration data · 15 October 2026</footer></main></div>`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.project);go('Project detail')});$('#role').onchange=e=>{role=e.target.value;go('Overview')};$('#search').onchange=e=>{filter=e.target.value.toLowerCase();if(page==='Overview'||page==='Projects'||page==='Sales & CRM')render();else {page='Projects';render()}};$('#signout').onclick=login;document.querySelectorAll('[data-tender]').forEach(b=>b.onclick=()=>tenderDetail(Number(b.dataset.tender)));if($('#addLead'))$('#addLead').onclick=addLead;if($('#capture'))$('#capture').onclick=addLead;document.querySelectorAll('[data-lead]').forEach(s=>s.onchange=()=>{leads[Number(s.dataset.lead)].stage=s.value;localStorage.setItem('sh-demo-leads',JSON.stringify(leads));toast('Demo lead stage updated')})}
login();
